package com.cowave.search.jdbc.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document

/**
 * JDBC 연결 설정 도큐먼트.
 *
 * 기존 ES `.dsearch_jdbc` 도큐먼트를 MongoDB로 이전.
 * - clusterId: 어느 클러스터에 속하는지 구분
 */
@Document(collection = "jdbc_info")
data class JdbcInfo(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    var name: String,
    var provider: String,
    var driver: String,
    var address: String,
    var port: String,
    var dbName: String,
    var user: String? = null,
    var password: String? = null,
    var url: String? = null,
    var params: String? = null,
)

package com.cowave.search.dynamicindex.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.mapping.Document

@Document(collection = "dynamic_index_info")
data class DynamicIndexInfo(
    @Id
    val id: String = ObjectId.get().toHexString(),
    var bundleQueue: String,
    var bundleServer: String,
    var scheme: String,
    var ip: String,
    var port: String,
    var stateEndPoint: String? = null,
    var consumeEndPoint: String? = null,
)

package com.cowave.search.notice

import org.slf4j.LoggerFactory
import org.springframework.scheduling.annotation.Async
import org.springframework.stereotype.Service
import org.springframework.web.client.RestClient

/**
 * Telegram Bot API를 통한 알림 서비스.
 *
 * - WebFlux 없이 spring-web의 RestClient 사용
 * - @Async로 비동기 처리 (색인 완료/실패 알림이 주 흐름을 블로킹하지 않도록)
 * - enabled=false 이면 전송 생략
 */
@Service
class TelegramNoticeService(
    private val restClientBuilder: RestClient.Builder,
    private val properties: TelegramProperties,
) {
    private val logger = LoggerFactory.getLogger(TelegramNoticeService::class.java)

    private val restClient: RestClient by lazy { restClientBuilder.build() }

    @Async
    fun sendMessage(text: String) {
        if (!properties.enabled) return
        if (properties.bot.isBlank() || properties.chat.isBlank()) {
            logger.warn("Telegram 설정이 올바르지 않습니다 (bot/chat 미설정)")
            return
        }

        runCatching {
            restClient
                .post()
                .uri("https://api.telegram.org/bot${properties.bot}/sendMessage")
                .body(mapOf("chat_id" to properties.chat, "text" to text))
                .retrieve()
                .toBodilessEntity()
        }.onFailure { e ->
            logger.warn("Telegram 알림 발송 실패: ${e.message}")
        }
    }
}

package com.cowave.search.pipeline.service

import co.elastic.clients.elasticsearch.ingest.Document
import co.elastic.clients.elasticsearch.ingest.Processor
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.pipeline.dto.PipelineInfo
import com.cowave.search.pipeline.dto.PutPipelineRequest
import com.cowave.search.pipeline.dto.SimulateDocResult
import com.cowave.search.pipeline.dto.SimulatePipelineRequest
import com.cowave.search.pipeline.dto.SimulatePipelineResponse
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class PipelineService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(PipelineService::class.java)

    fun listPipelines(
        clusterId: String,
        id: String? = null,
    ): List<PipelineInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { req -> id?.let { req.id(it) } ?: req }
            response.pipelines().map { (pipelineId, pipeline) ->
                val processors =
                    pipeline.processors().map { proc ->
                        mapOf("type" to proc._kind().jsonValue())
                    }
                PipelineInfo(
                    id = pipelineId,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = processors,
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getPipeline(
        clusterId: String,
        id: String,
    ): PipelineInfo? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { it.id(id) }
            response.pipelines()[id]?.let { pipeline ->
                PipelineInfo(
                    id = id,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = pipeline.processors().map { mapOf("type" to it._kind().jsonValue()) },
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 조회 실패 [{}/{}]: {}", clusterId, id, e.message)
            null
        }
    }

    fun putPipeline(
        clusterId: String,
        id: String,
        request: PutPipelineRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        val mapper =
            com.fasterxml.jackson.databind
                .ObjectMapper()

        client.ingest().putPipeline { req ->
            req
                .id(id)
                .apply {
                    request.description?.let { description(it) }
                    request.version?.let { version(it) }
                    if (request.processors.isNotEmpty()) {
                        processors(
                            request.processors.map { procMap ->
                                val procJson = mapper.writeValueAsString(procMap)
                                Processor.of { p ->
                                    p.withJson(java.io.StringReader(procJson))
                                }
                            },
                        )
                    }
                }
        }
        logger.info("파이프라인 저장: {}/{}", clusterId, id)
    }

    fun deletePipeline(
        clusterId: String,
        id: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.ingest().deletePipeline { it.id(id) }
        logger.info("파이프라인 삭제: {}/{}", clusterId, id)
    }

    fun simulatePipeline(
        clusterId: String,
        pipelineId: String?,
        request: SimulatePipelineRequest,
    ): SimulatePipelineResponse {
        val client = clientFactory.getClient(clusterId)
        val mapper =
            com.fasterxml.jackson.databind
                .ObjectMapper()

        // ES 9.x: client.simulate().ingest() API 사용
        val docs =
            request.docs.map { doc ->
                val sourceJson = mapper.writeValueAsString(doc.source)
                Document.of { d ->
                    d
                        .index(doc.index)
                        .apply { doc.id?.let { id(it) } }
                        .withJson(java.io.StringReader(sourceJson))
                }
            }

        val response =
            client.simulate().ingest { req ->
                pipelineId?.let { req.pipeline(it) }
                req.docs(docs)
            }

        val results =
            response.docs().map { docResult ->
                val docSim = docResult.doc()
                val error = docSim?.error()
                if (error != null) {
                    SimulateDocResult(
                        docId = docSim.id(),
                        index = docSim.index(),
                        source = emptyMap(),
                        error = error.reason(),
                    )
                } else {
                    @Suppress("UNCHECKED_CAST")
                    val source = docSim?.source()?.mapValues { (_, v) -> v.to(Any::class.java) } ?: emptyMap()
                    SimulateDocResult(
                        docId = docSim?.id(),
                        index = docSim?.index(),
                        source = source,
                        processorResults = emptyList(),
                    )
                }
            }

        return SimulatePipelineResponse(docs = results)
    }
}

