    fun listIndices(
        clusterId: String,
        pattern: String = "*",
        excludeSystem: Boolean = true,
    ): List<IndexInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val statsResponse = client.indices().stats { it.index(pattern) }
            val aliasResponse =
                runCatching {
                    client.indices().getAlias { it.index(pattern) }
                }.getOrNull()

            statsResponse.indices()?.mapNotNull { (indexName, indexStats) ->
                if (excludeSystem && indexName.startsWith(".")) return@mapNotNull null

                val aliases =
                    aliasResponse
                        ?.aliases()
                        ?.get(indexName)
                        ?.aliases()
                        ?.keys
                        ?.toList() ?: emptyList()

                IndexInfo(
                    name = indexName,
                    health = null,
                    status = null,
                    docsCount = indexStats.total()?.docs()?.count(),
                    storeSizeBytes = indexStats.total()?.store()?.sizeInBytes(),
                    primaryShards = null,
                    replicaShards = null,
                    aliases = aliases,
                )
            } ?: emptyList()
        }.getOrElse { e ->
            logger.warn("인덱스 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
