        val docsCount =
            runCatching {
                client
                    .indices()
                    .stats { it.index(indexName) }
                    .indices()
                    ?.get(indexName)
                    ?.total()
                    ?.docs()
                    ?.count()
            }.getOrNull()

        val storeSizeBytes =
            runCatching {
                client
                    .indices()
                    .stats { it.index(indexName) }
                    .indices()
                    ?.get(indexName)
