                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }

        // analysis=true 시 문서별/필드별 토큰 분석
        val analyzeDocumentTermMap: Map<String, Map<String, List<String>>> =
            if (analysis && documents.isNotEmpty()) {
                documents.associate { doc ->
                    val docId = doc["_id"]?.toString() ?: ""
                    val fieldTerms =
                        fields
                            .mapNotNull { fieldName ->
                                val value = doc[fieldName]?.toString() ?: return@mapNotNull null
                                val tokens =
                                    runCatching {
                                        client
                                            .indices()
                                            .analyze { a ->
                                                a.index(indexName).field(fieldName).text(value)
                                            }.tokens()
                                            .map { it.token() }
                                    }.getOrElse { emptyList() }
                                fieldName to tokens
                            }.toMap()
                    docId to fieldTerms
                }
            } else {
                emptyMap()
            }

        return DocumentPagination(
            fields = fields,
            hits = documents,
            totalCount = totalCount,
            lastPageNum = lastPageNum,
            pageNum = pageNum,
            rowSize = rowSize,
            analyzeDocumentTermMap = analyzeDocumentTermMap,
        )
    }

    // ── 필드별 분석기 실행 (analyzer) ─────────────────────────────────────

    /**
     * POST /indices/{index}/analyzer
     *
     * 특정 문서(docId)의 각 필드 텍스트를 인덱스 매핑 analyzer로 토큰 분석한다.
     * docId 없이 texts를 직접 전달할 경우 fields와 texts를 1:1 매핑하여 분석한다.
     */
    fun analyzeFields(
        clusterId: String,
        indexName: String,
        request: FieldAnalyzeRequest,
    ): FieldAnalyzeResponse {
        val client = clientFactory.getClient(clusterId)

        // 분석 대상 필드 목록: 요청에 없으면 매핑 전체 필드
        val targetFields =
            request.fields
                ?: runCatching {
                    client
                        .indices()
                        .getMapping { it.index(indexName) }
                        .mappings()[indexName]
                        ?.mappings()
                        ?.properties()
                        ?.keys
                        ?.toList() ?: emptyList()
                }.getOrElse { emptyList() }

        // docId가 있으면 ES에서 문서 조회 후 필드값 추출
        val sourceDoc: Map<String, Any?> =
            if (request.docId != null) {
                runCatching {
                    val resp =
                        client.search(
                            { s ->
                                s
                                    .index(indexName)
                                    .size(1)
                                    .query { q -> q.ids { it.values(request.docId) } }
                            },
                            Map::class.java,
                        )
                    @Suppress("UNCHECKED_CAST")
                    resp.hits().hits().firstOrNull()?.source() as? Map<String, Any?> ?: emptyMap()
                }.getOrElse { emptyMap() }
            } else {
                emptyMap()
            }

        val fieldTermMap =
            targetFields
                .mapIndexedNotNull { idx, fieldName ->
                    val text =
                        when {
                            sourceDoc.isNotEmpty() -> sourceDoc[fieldName]?.toString()
                            request.texts != null && idx < request.texts.size -> request.texts[idx]
                            else -> null
                        } ?: return@mapIndexedNotNull null

                    val tokens =
                        runCatching {
                            client
                                .indices()
                                .analyze { a -> a.index(indexName).field(fieldName).text(text) }
                                .tokens()
                                .map { it.token() }
                        }.getOrElse { emptyList() }

                    fieldName to tokens
                }.toMap()

        return FieldAnalyzeResponse(index = indexName, fieldTermMap = fieldTermMap)
    }
}

// 확장 함수: Map을 ES Query JSON 리더로 변환
private fun Map<String, Any>.toJsonReader(): java.io.Reader {
    val json =
        com.fasterxml.jackson.databind
            .ObjectMapper()
            .writeValueAsString(this)
    return java.io.StringReader(json)
}

