package com.cowave.search.indices.service

import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch.core.search.SourceConfig
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.common.util.toJsonReader
import com.cowave.search.indices.dto.AnalyzeRequest
import com.cowave.search.indices.dto.AnalyzeResponse
import com.cowave.search.indices.dto.AnalyzeToken
import com.cowave.search.indices.dto.DocumentSearchRequest
import com.cowave.search.indices.dto.DocumentSearchResponse
import com.cowave.search.indices.dto.DocumentPagination
import com.cowave.search.indices.dto.FieldAnalyzeRequest
import com.cowave.search.indices.dto.FieldAnalyzeResponse
import com.cowave.search.indices.dto.IndexDetail
import com.cowave.search.indices.dto.IndexInfo
import com.cowave.search.indices.dto.IndexMappingResponse
import com.cowave.search.indices.dto.IndexSettingsResponse
import com.cowave.search.indices.dto.OpenPitResponse
import kotlin.math.ceil
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class IndicesService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(IndicesService::class.java)

    // ── 인덱스 목록 조회 ──────────────────────────────────────────────────

    fun listIndices(
        clusterId: String,
        pattern: String = "*",
        excludeSystem: Boolean = true,
    ): List<IndexInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val statsResponse = client.indices().stats { it.index(pattern) }
            val aliasResponse =
                runCatching {
                    client.indices().getAlias { it.index(pattern) }
                }.getOrNull()

            statsResponse.indices()?.mapNotNull { (indexName, indexStats) ->
                if (excludeSystem && indexName.startsWith(".")) return@mapNotNull null

                val aliases =
                    aliasResponse
                        ?.aliases()
                        ?.get(indexName)
                        ?.aliases()
                        ?.keys
                        ?.toList() ?: emptyList()

                IndexInfo(
                    name = indexName,
                    health = null,
                    status = null,
                    docsCount = indexStats.total()?.docs()?.count(),
                    storeSizeBytes = indexStats.total()?.store()?.sizeInBytes(),
                    primaryShards = null,
                    replicaShards = null,
                    aliases = aliases,
                )
            } ?: emptyList()
        }.getOrElse { e ->
            logger.warn("인덱스 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    // ── 인덱스 상세 조회 ──────────────────────────────────────────────────

    fun getIndexDetail(
        clusterId: String,
        indexName: String,
    ): IndexDetail {
        val client = clientFactory.getClient(clusterId)

        val aliases =
            runCatching {
                client
                    .indices()
                    .getAlias { it.index(indexName) }
                    .aliases()[indexName]
                    ?.aliases()
                    ?.keys
                    ?.toList() ?: emptyList()
            }.getOrElse { emptyList() }

        val docsCount =
            runCatching {
                client
                    .indices()
                    .stats { it.index(indexName) }
                    .indices()
                    ?.get(indexName)
                    ?.total()
                    ?.docs()
                    ?.count()
            }.getOrNull()

        val storeSizeBytes =
            runCatching {
                client
                    .indices()
                    .stats { it.index(indexName) }
                    .indices()
                    ?.get(indexName)
                    ?.total()
                    ?.store()
                    ?.sizeInBytes()
            }.getOrNull()

        val mappingsMap =
            runCatching {
                client
                    .indices()
                    .getMapping { it.index(indexName) }
                    .mappings()[indexName]
                    ?.mappings()
                    ?.properties()
                    ?.mapValues { (_, prop) -> prop.toString() } ?: emptyMap()
            }.getOrElse { emptyMap() }

        val settingsMap =
            runCatching {
                val raw =
                    client
                        .indices()
                        .getSettings { it.index(indexName) }
                        .settings()[indexName]
                        ?.settings()
                        ?.toString()
                if (raw != null) mapOf("raw" to raw) else emptyMap()
            }.getOrElse { emptyMap() }

        return IndexDetail(
            name = indexName,
            health = null,
            status = null,
            docsCount = docsCount,
            storeSizeBytes = storeSizeBytes,
            primaryShards = null,
            replicaShards = null,
            aliases = aliases,
            mappings = mappingsMap,
            settings = settingsMap,
        )
    }

    // ── 문서 조회 (Search After + PIT) ───────────────────────────────────

    fun searchDocuments(
        clusterId: String,
        indexName: String,
        request: DocumentSearchRequest,
    ): DocumentSearchResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            client.search(
                { s ->
                    s
                        .index(indexName)
                        .size(request.size)
                        .source(SourceConfig.of { it.fetch(true) })
                        .apply {
                            if (request.pitId != null) {
                                pit { p -> p.id(request.pitId).keepAlive { t -> t.time("1m") } }
                            } else {
                                from(request.from)
                            }
                            request.query?.let { q ->
                                query { qb -> qb.withJson(q.toJsonReader()) }
                            }
                            if (request.sort != null) {
                                request.sort.forEach { sortItem ->
                                    sortItem.forEach { (field, order) ->
                                        sort { so ->
                                            so.field { f ->
                                                f
                                                    .field(field)
                                                    .order(
                                                        if (order.toString().uppercase() == "DESC") {
                                                            SortOrder.Desc
                                                        } else {
                                                            SortOrder.Asc
                                                        },
                                                    )
                                            }
                                        }
                                    }
                                }
                            }
                            request.searchAfter?.let { sa ->
                                searchAfter(
                                    sa.map { v ->
                                        co.elastic.clients.elasticsearch._types.FieldValue
                                            .of(v.toString())
                                    },
                                )
                            }
                        }
                },
                Map::class.java,
            )

        val hits = response.hits().hits()
        val documents =
            hits.map { hit ->
                @Suppress("UNCHECKED_CAST")
                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }
        val lastSearchAfter = hits.lastOrNull()?.sort()?.map { it._get() }

        return DocumentSearchResponse(
            total = response.hits().total()?.value() ?: 0L,
            hits = documents,
            pitId = response.pitId(),
            searchAfter = lastSearchAfter,
        )
    }

    // ── PIT 관리 ─────────────────────────────────────────────────────────

    fun openPit(
        clusterId: String,
        indexName: String,
        keepAlive: String = "5m",
    ): OpenPitResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.openPointInTime { it.index(indexName).keepAlive { t -> t.time(keepAlive) } }
        return OpenPitResponse(pitId = response.id())
    }

    fun closePit(
        clusterId: String,
        pitId: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        runCatching {
            client.closePointInTime { it.id(pitId) }
        }.onFailure { e ->
            logger.warn("PIT 닫기 실패 [{}]: {}", pitId, e.message)
        }
    }

    // ── 분석기 실행 ───────────────────────────────────────────────────────

    fun analyze(
        clusterId: String,
        request: AnalyzeRequest,
    ): AnalyzeResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            if (request.index != null) {
                client.indices().analyze { a ->
                    a
                        .index(request.index)
                        .text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let {
                                filter(
                                    it.map { f ->
                                        co.elastic.clients.elasticsearch._types.analysis.TokenFilter
                                            .of { t -> t.name(f) }
                                    },
                                )
                            }
                            request.charFilter?.let {
                                charFilter(
                                    it.map { f ->
                                        co.elastic.clients.elasticsearch._types.analysis.CharFilter
                                            .of { t -> t.name(f) }
                                    },
                                )
                            }
                        }
                }
            } else {
                client.indices().analyze { a ->
                    a
                        .text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let {
                                filter(
                                    it.map { f ->
                                        co.elastic.clients.elasticsearch._types.analysis.TokenFilter
                                            .of { t -> t.name(f) }
                                    },
                                )
                            }
                            request.charFilter?.let {
                                charFilter(
                                    it.map { f ->
                                        co.elastic.clients.elasticsearch._types.analysis.CharFilter
                                            .of { t -> t.name(f) }
                                    },
                                )
                            }
                        }
                }
            }

        val tokens =
            response.tokens().map { token ->
                AnalyzeToken(
                    token = token.token(),
                    startOffset = token.startOffset().toInt(),
                    endOffset = token.endOffset().toInt(),
                    type = token.type(),
                    position = token.position().toInt(),
                )
            }

        return AnalyzeResponse(tokens = tokens)
    }

    // ── 매핑 조회 ─────────────────────────────────────────────────────────

    fun getMapping(
        clusterId: String,
        indexName: String,
    ): IndexMappingResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getMapping { it.index(indexName) }
        val mappingRecord = response.mappings()[indexName]
        val mappingsMap =
            mappingRecord
                ?.mappings()
                ?.properties()
                ?.mapValues { (_, prop) -> prop.toString() } ?: emptyMap()

        return IndexMappingResponse(index = indexName, mappings = mappingsMap)
    }

    // ── 설정 조회 ─────────────────────────────────────────────────────────

    fun getSettings(
        clusterId: String,
        indexName: String,
    ): IndexSettingsResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getSettings { it.index(indexName) }
        val indexState = response.settings()[indexName]
        val settingsMap = indexState?.settings()?.toString()?.let { mapOf("raw" to it) } ?: emptyMap()

        return IndexSettingsResponse(index = indexName, settings = settingsMap)
    }

    // ── 문서 페이지네이션 조회 (_docs) ────────────────────────────────────

    /**
     * GET /indices/{index}/_docs
     *
     * analysis=true 시 각 문서의 각 필드에 대해 인덱스 매핑 analyzer로 토큰 분석을 수행하고
     * analyzeDocumentTermMap에 결과를 채워 반환한다.
     * id 파라미터가 있으면 해당 문서 1건만 조회한다.
     */
    fun getDocumentsPaginated(
        clusterId: String,
        indexName: String,
        pageNum: Int = 1,
        rowSize: Int = 10,
        analysis: Boolean = false,
        id: String? = null,
    ): DocumentPagination {
        val client = clientFactory.getClient(clusterId)

        // 인덱스 필드 목록 (매핑에서 추출)
        val fields =
            runCatching {
                client
                    .indices()
                    .getMapping { it.index(indexName) }
                    .mappings()[indexName]
                    ?.mappings()
                    ?.properties()
                    ?.keys
                    ?.toList() ?: emptyList()
            }.getOrElse { emptyList() }

        // 검색 쿼리 구성
        val from = (pageNum - 1) * rowSize
        val response =
            client.search(
                { s ->
                    s
                        .index(indexName)
                        .size(rowSize)
                        .from(if (id != null) 0 else from)
                        .apply {
                            if (id != null) {
                                query { q -> q.ids { it.values(id) } }
                            } else {
                                query { q -> q.matchAll { it } }
                            }
                        }
                },
                Map::class.java,
            )

        val hits = response.hits().hits()
        val totalCount = response.hits().total()?.value() ?: 0L
        val lastPageNum = if (rowSize > 0) ceil(totalCount.toDouble() / rowSize).toInt().coerceAtLeast(1) else 1

        @Suppress("UNCHECKED_CAST")
        val documents =
            hits.map { hit ->
                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }

        // analysis=true 시 문서별/필드별 토큰 분석
        val analyzeDocumentTermMap: Map<String, Map<String, List<String>>> =
            if (analysis && documents.isNotEmpty()) {
                documents.associate { doc ->
                    val docId = doc["_id"]?.toString() ?: ""
                    val fieldTerms =
                        fields
                            .mapNotNull { fieldName ->
                                val value = doc[fieldName]?.toString() ?: return@mapNotNull null
                                val tokens =
                                    runCatching {
                                        client
                                            .indices()
                                            .analyze { a ->
                                                a.index(indexName).field(fieldName).text(value)
                                            }.tokens()
                                            .map { it.token() }
                                    }.getOrElse { emptyList() }
                                fieldName to tokens
                            }.toMap()
                    docId to fieldTerms
                }
            } else {
                emptyMap()
            }

        return DocumentPagination(
            fields = fields,
            hits = documents,
            totalCount = totalCount,
            lastPageNum = lastPageNum,
            pageNum = pageNum,
            rowSize = rowSize,
            analyzeDocumentTermMap = analyzeDocumentTermMap,
        )
    }

    // ── 필드별 분석기 실행 (analyzer) ─────────────────────────────────────

    /**
     * POST /indices/{index}/analyzer
     *
     * 특정 문서(docId)의 각 필드 텍스트를 인덱스 매핑 analyzer로 토큰 분석한다.
     * docId 없이 texts를 직접 전달할 경우 fields와 texts를 1:1 매핑하여 분석한다.
     */
    fun analyzeFields(
        clusterId: String,
        indexName: String,
        request: FieldAnalyzeRequest,
    ): FieldAnalyzeResponse {
        val client = clientFactory.getClient(clusterId)

        // 분석 대상 필드 목록: 요청에 없으면 매핑 전체 필드
        val targetFields =
            request.fields
                ?: runCatching {
                    client
                        .indices()
                        .getMapping { it.index(indexName) }
                        .mappings()[indexName]
                        ?.mappings()
                        ?.properties()
                        ?.keys
                        ?.toList() ?: emptyList()
                }.getOrElse { emptyList() }

        // docId가 있으면 ES에서 문서 조회 후 필드값 추출
        val sourceDoc: Map<String, Any?> =
            if (request.docId != null) {
                runCatching {
                    val resp =
                        client.search(
                            { s ->
                                s
                                    .index(indexName)
                                    .size(1)
                                    .query { q -> q.ids { it.values(request.docId) } }
                            },
                            Map::class.java,
                        )
                    @Suppress("UNCHECKED_CAST")
                    resp.hits().hits().firstOrNull()?.source() as? Map<String, Any?> ?: emptyMap()
                }.getOrElse { emptyMap() }
            } else {
                emptyMap()
            }

        val fieldTermMap =
            targetFields
                .mapIndexedNotNull { idx, fieldName ->
                    val text =
                        when {
                            sourceDoc.isNotEmpty() -> sourceDoc[fieldName]?.toString()
                            request.texts != null && idx < request.texts.size -> request.texts[idx]
                            else -> null
                        } ?: return@mapIndexedNotNull null

                    val tokens =
                        runCatching {
                            client
                                .indices()
                                .analyze { a -> a.index(indexName).field(fieldName).text(text) }
                                .tokens()
                                .map { it.token() }
                        }.getOrElse { emptyList() }

                    fieldName to tokens
                }.toMap()

        return FieldAnalyzeResponse(index = indexName, fieldTermMap = fieldTermMap)
    }
}

// 확장 함수: Map을 ES Query JSON 리더로 변환
private fun Map<String, Any>.toJsonReader(): java.io.Reader {
    val json =
        com.fasterxml.jackson.databind
            .ObjectMapper()
            .writeValueAsString(this)
    return java.io.StringReader(json)
}

