package com.cowave.search.template.service

import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.template.dto.ComponentTemplateInfo
import com.cowave.search.template.dto.IndexTemplateInfo
import com.cowave.search.template.dto.PutComponentTemplateRequest
import com.cowave.search.template.dto.PutIndexTemplateRequest
import com.cowave.search.template.dto.SYSTEM_TEMPLATE_PREFIXES
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class TemplateService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(TemplateService::class.java)

    // ── Composable Index Template CRUD ────────────────────────────────────

    fun listIndexTemplates(
        clusterId: String,
        name: String? = null,
        excludeSystem: Boolean = true,
    ): List<IndexTemplateInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.indices().getIndexTemplate { req -> name?.let { req.name(it) } ?: req }
            response
                .indexTemplates()
                .filter { tmpl ->
                    !excludeSystem || SYSTEM_TEMPLATE_PREFIXES.none { prefix -> tmpl.name().startsWith(prefix) }
                }.map { tmpl ->
                    val tpl = tmpl.indexTemplate()
                    IndexTemplateInfo(
                        name = tmpl.name(),
                        indexPatterns = tpl.indexPatterns(),
                        priority = tpl.priority()?.toInt(),
                        version = tpl.version(),
                        composedOf = tpl.composedOf(),
                        mappings =
                            tpl
                                .template()
                                ?.mappings()
                                ?.toString()
                                ?.let { mapOf("raw" to it) },
                        settings =
                            tpl
                                .template()
                                ?.settings()
                                ?.toString()
                                ?.let { mapOf("raw" to it) },
                        dataStream = tpl.dataStream() != null,
                    )
                }
        }.getOrElse { e ->
            logger.warn("인덱스 템플릿 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getIndexTemplate(
        clusterId: String,
        name: String,
    ): IndexTemplateInfo? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.indices().getIndexTemplate { it.name(name) }
            response.indexTemplates().firstOrNull()?.let { tmpl ->
                val tpl = tmpl.indexTemplate()
                IndexTemplateInfo(
                    name = tmpl.name(),
                    indexPatterns = tpl.indexPatterns(),
                    priority = tpl.priority()?.toInt(),
                    version = tpl.version(),
                    composedOf = tpl.composedOf(),
                    mappings =
                        tpl
                            .template()
                            ?.mappings()
                            ?.toString()
                            ?.let { mapOf("raw" to it) },
                    settings =
                        tpl
                            .template()
                            ?.settings()
                            ?.toString()
                            ?.let { mapOf("raw" to it) },
                    dataStream = tpl.dataStream() != null,
                )
            }
        }.getOrElse { e ->
            logger.warn("인덱스 템플릿 조회 실패 [{}/{}]: {}", clusterId, name, e.message)
            null
        }
    }

    fun putIndexTemplate(
        clusterId: String,
        name: String,
        request: PutIndexTemplateRequest,
